ALTER TABLE intake_cases ADD COLUMN visit_stage text NOT NULL DEFAULT 'expected' CHECK(visit_stage IN ('expected','arrived','awaiting_triage','waiting_for_assessment','in_assessment','in_care','completed','transferred','left_before_assessment','canceled'));
ALTER TABLE clinical_assessments ADD COLUMN priority text NOT NULL DEFAULT 'unassessed' CHECK(priority IN ('unassessed','immediate','urgent','assessed_stable'));
ALTER TABLE clinical_assessments ADD COLUMN instruction text;
CREATE TABLE visit_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES intake_cases(id),actor_id text NOT NULL,old_stage text NOT NULL,new_stage text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE staff_coverage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),location_id uuid NOT NULL REFERENCES provider_locations(id),role text NOT NULL,staff_count integer NOT NULL CHECK(staff_count>=0 AND staff_count<=100),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL CHECK(ends_at>starts_at),created_by text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE schedule_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),location_id uuid NOT NULL REFERENCES provider_locations(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL CHECK(ends_at>starts_at),created_by text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE slot_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slot_id uuid NOT NULL REFERENCES schedule_slots(id),case_id uuid NOT NULL REFERENCES intake_cases(id),state text NOT NULL DEFAULT 'requested' CHECK(state IN ('requested','confirmed','canceled','completed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(slot_id,case_id));
CREATE UNIQUE INDEX one_confirmed_request_per_slot ON slot_requests(slot_id) WHERE state='confirmed';
CREATE TABLE handoffs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),case_id uuid NOT NULL REFERENCES intake_cases(id),sending_location_id uuid NOT NULL REFERENCES provider_locations(id),receiving_location_id uuid NOT NULL REFERENCES provider_locations(id),created_by text NOT NULL,instruction text NOT NULL,owner_authorized boolean NOT NULL CHECK(owner_authorized),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','acknowledged','information_requested','declined','closed')),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(sending_location_id<>receiving_location_id));
CREATE TABLE case_share_grants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),handoff_id uuid NOT NULL UNIQUE REFERENCES handoffs(id),case_id uuid NOT NULL REFERENCES intake_cases(id),receiving_location_id uuid NOT NULL REFERENCES provider_locations(id),expires_at timestamptz NOT NULL,revoked_at timestamptz);
